func (s PtrMapHeavy) JSONSize() int {
	size := 6
	if s.M == nil {
		size += 4
	} else {
		size += 4
		size += len((*s.M)) * 4
		for k, v := range *s.M {
			size += len(k) * 2
			size += v.JSONSize()
		}
	}
	return size
}

func (s PtrMapHeavy) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"m\":"...)
	if s.M == nil {
		dst = append(dst, "null"...)
	} else {
		if (*s.M) == nil {
			dst = append(dst, "null"...)
		} else {
			dst = append(dst, '{')
			firstM := true
			for k, v := range *s.M {
				if firstM {
					firstM = false
					dst = append(dst, '"')
				} else {
					dst = append(dst, ",\""...)
				}
				dst = ggen.AppendStringNoHTML(dst, k)
				dst = append(dst, ':')
				if dst, err = v.AppendJSON(dst); err != nil {
					return dst, err
				}
			}
			dst = append(dst, '}')
		}
	}
	return append(dst, '}'), nil
}
